/** The issues deliberately planted in the data. */
export const PLANTED = {
  missingShipments: ["O-1007", "O-1013", "O-1022", "O-1029", "O-1034"],
  nullShipmentStatus: ["O-1004", "O-1016", "O-1031"],
  splitShipment: "O-1018",
  duplicateTxns: { "T-50006": 2, "T-50014": 3, "T-50027": 2, "T-50033": 2 } as Record<string, number>,
  declinedTxns: ["T-50012", "T-50035"],
  unsettledTxns: ["T-50020", "T-50039"],
  amountMismatches: ["T-50009", "T-50017", "T-50024", "T-50038"],
  delayedSettlements: { "T-50003": 4, "T-50014": 5, "T-50021": 3, "T-50027": 6, "T-50030": 4, "T-50036": 5 } as Record<string, number>,
};

const pad = (n: number) => String(n).padStart(2, "0");
const round2 = (n: number) => Math.round(n * 100) / 100;
const addDays = (iso: string, days: number) => {
  const d = new Date(`${iso}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
};
const lit = (v: string | number | null) => (v === null ? "NULL" : typeof v === "number" ? String(v) : `'${v.replace(/'/g, "''")}'`);
const insert = (table: string, rows: (string | number | null)[][]) =>
  rows.length ? `INSERT INTO ${table} VALUES\n${rows.map((r) => `  (${r.map(lit).join(", ")})`).join(",\n")};\n` : "";

function shippingRows() {
  const warehouses = [
    ["W01", "North Hub", "Chicago", "IL"],
    ["W02", "Lakeshore DC", "Milwaukee", "WI"],
    ["W03", "Twin Cities DC", "Minneapolis", "MN"],
    ["W04", "Gulf Coast DC", "Houston", "TX"],
    ["W05", "Desert DC", "Phoenix", "AZ"],
  ];
  const orders: (string | number)[][] = [];
  const shipments: (string | number | null)[][] = [];
  const carriers = ["UPS", "FedEx", "USPS", "Freight"];
  for (let i = 1; i <= 36; i++) {
    const id = `O-${1000 + i}`;
    const orderDate = `2026-09-${pad(1 + ((i - 1) % 28))}`;
    orders.push([id, `C-${200 + ((i * 7) % 15)}`, `W0${(i % 5) + 1}`, orderDate, round2(((i * 37) % 200) + 25.5 + i * 0.25)]);
    if (PLANTED.missingShipments.includes(id)) continue;
    const shipped = addDays(orderDate, 1 + (i % 3));
    const delivered = i % 3 !== 0;
    const status = PLANTED.nullShipmentStatus.includes(id) ? null : delivered ? "delivered" : "in_transit";
    shipments.push([`S-${5000 + i}`, id, carriers[i % 4], status, shipped, delivered ? addDays(shipped, 2) : null]);
    if (id === PLANTED.splitShipment) shipments.push(["S-5100", id, "Freight", "delivered", addDays(shipped, 1), addDays(shipped, 3)]);
  }
  return { warehouses, orders, shipments };
}

function paymentRows() {
  const merchants = [
    ["M01", "Copper Kettle Cafe", "Food & beverage", "US"],
    ["M02", "Bluebird Books", "Retail", "US"],
    ["M03", "Summit Outdoor", "Sporting goods", "US"],
    ["M04", "Pixel Arcade", "Entertainment", "US"],
    ["M05", "Harbor Florist", "Retail", "US"],
    ["M06", "Atlas Auto Parts", "Automotive", "US"],
  ];
  const transactions: (string | number)[][] = [];
  const settlements: (string | number)[][] = [];
  for (let i = 1; i <= 40; i++) {
    const id = `T-${50000 + i}`;
    const merchant = `M0${((i * 5) % 6) + 1}`;
    const amount = round2(10 + ((i * 53) % 180) + ((i * 7) % 100) / 100);
    const date = `2026-10-${pad(1 + ((i - 1) % 20))}`;
    const declined = PLANTED.declinedTxns.includes(id);
    const row = [id, merchant, amount, "USD", date, declined ? "declined" : "captured"];
    for (let copy = 0; copy < (PLANTED.duplicateTxns[id] ?? 1); copy++) transactions.push(row);
    if (declined || PLANTED.unsettledTxns.includes(id)) continue;
    const settled =
      id === "T-50009" ? amount - 0.3 : id === "T-50017" ? amount + 9 : id === "T-50024" ? amount / 2 : id === "T-50038" ? amount - 1.25 : amount;
    settlements.push([`ST-${70000 + i}`, id, merchant, round2(settled), addDays(date, PLANTED.delayedSettlements[id] ?? 1)]);
  }
  return { merchants, transactions, settlements };
}

const ship = shippingRows();
const pay = paymentRows();

/** Complete SQL that builds the disposable database: schema plus synthetic rows. */
export const DATABASE_SQL = `-- Synthetic demonstration data. Not real company, customer or payment records.
CREATE TABLE warehouses (warehouse_id TEXT PRIMARY KEY, name TEXT NOT NULL, city TEXT, state TEXT);
CREATE TABLE orders (order_id TEXT PRIMARY KEY, customer_id TEXT, warehouse_id TEXT REFERENCES warehouses, order_date TEXT, total_amount REAL);
CREATE TABLE shipments (shipment_id TEXT PRIMARY KEY, order_id TEXT REFERENCES orders, carrier TEXT, status TEXT, shipped_date TEXT, delivered_date TEXT);
CREATE TABLE merchants (merchant_id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT, country TEXT);
CREATE TABLE transactions (txn_id TEXT, merchant_id TEXT REFERENCES merchants, amount REAL, currency TEXT, txn_date TEXT, status TEXT);
CREATE TABLE settlements (settlement_id TEXT PRIMARY KEY, txn_id TEXT, merchant_id TEXT REFERENCES merchants, settled_amount REAL, settlement_date TEXT);
${insert("warehouses", ship.warehouses)}${insert("orders", ship.orders)}${insert("shipments", ship.shipments)}${insert("merchants", pay.merchants)}${insert(
  "transactions",
  pay.transactions,
)}${insert("settlements", pay.settlements)}`;

